SELECT COUNT(*) AS total_listings_at_iv
FROM nlq.listings
WHERE meetup_spot ILIKE '%International Village%';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT name
FROM nlq.meetup_spots
WHERE area = 'on campus';

SELECT COUNT(*) AS board_game_count
FROM nlq.listings
WHERE (title ILIKE '%board%' OR description ILIKE '%board%');

SELECT ROUND(percentile_cont(0.5) WITHIN GROUP (ORDER BY rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_listings
FROM nlq.listings
WHERE (title ILIKE '%pickup only%' OR description ILIKE '%pickup only%');

SELECT COUNT(*) AS listings_posted_since_oct_1
FROM nlq.listings
WHERE (listed_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-10-01';

SELECT COUNT(*) AS review_count
FROM nlq.my_reviews
WHERE direction = 'given';

SELECT COUNT(*) AS five_star_received
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT COALESCE(SUM(agreed_price), 0) AS total_spent
FROM nlq.my_deals
WHERE my_role = 'buyer' AND status = 'completed';

SELECT COUNT(*) AS reviews_under_4_stars
FROM nlq.my_reviews
WHERE direction = 'received' AND rating < 4;

SELECT COUNT(DISTINCT category) AS distinct_categories_bought
FROM nlq.my_deals
WHERE my_role = 'buyer' AND deal_type = 'sale' AND status = 'completed';

SELECT ROUND(COALESCE(SUM(agreed_price),0)::numeric, 2) AS total_revenue
FROM nlq.deals
WHERE deal_type = 'rental' AND status = 'completed';

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT round(100.0 * SUM(CASE WHEN d.status = 'cancelled' THEN 1 ELSE 0 END) / COUNT(*)::numeric, 2) AS cancelled_percent
FROM nlq.deals d
WHERE d.deal_type = 'sale';

SELECT COUNT(*) AS reserved_listings
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS like_new_count
FROM nlq.listings_all
WHERE condition = 'like_new';

SELECT COUNT(*) AS suspended_account_count
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS resolved_report_count
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_1_star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS listing_report_count
FROM nlq.reports
WHERE target_type = 'listing';

select count(*) as rented_out_count
from nlq.listings_all
where status = 'rented_out';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT COUNT(*) AS buyer_more_messages
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT round(100.0 * SUM(CASE WHEN rating = 5 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_5stars
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT COUNT(*) AS report_count
FROM nlq.reports
WHERE reason ILIKE '%deposit%' OR reason ILIKE '%deposit%';

SELECT COUNT(*) AS students_never_posted
FROM nlq.students s
WHERE NOT EXISTS (
  SELECT 1 FROM nlq.listings_all la WHERE la.seller_id = s.student_id
);

SELECT round(100.0 * SUM(CASE WHEN status = 'removed' THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_removed
FROM nlq.listings_all
WHERE condition = 'good';

SELECT round(100.0 * SUM(CASE WHEN resolved_at - filed_at <= interval '48 hours' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percent_closed_in_48_hours
FROM nlq.reports
WHERE status = 'resolved';

SELECT ROUND(100.0 * AVG(CASE WHEN rating >= 4.5 THEN 1 ELSE 0 END), 2) AS avg_percent_above_4_5
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT COUNT(*) AS items_with_zero_bookmarks
FROM nlq.listings_all la
WHERE NOT EXISTS (
  SELECT 1 FROM nlq.saved_items si WHERE si.item_id = la.item_id
);
